function formatValidationErrors(errors: Array<{instancePath?: string; keyword?: string; params?: Record<string, unknown>}>): string {
  if (errors.length === 0) return 'Validation failed';

  const messages = errors.map(err => {
    const path = err.instancePath || 'root';
    if (err.keyword === 'required' && err.params?.missingProperty) {
      return `Missing required field: '${err.params.missingProperty}'`;
    }
    if (err.keyword === 'type' && err.params?.type) {
      return `Field '${path}' must be of type '${err.params.type}'`;
    }
    if (err.keyword === 'enum' && err.params?.allowedValues) {
      const values = (err.params.allowedValues as unknown[]).map(v => `'${v}'`).join(', ');
      return `Field '${path}' must be one of: ${values}`;
    }
    return `Field '${path}' validation failed`;
  });

  return messages.join('; ');
}

